.darma-loader-tw-bounce-dots { display: inline-flex; align-items: flex-end; justify-content: center; gap: calc(var(--loader-size, 72px) * .12); width: var(--loader-size, 72px); height: calc(var(--loader-size, 72px) * .5); }
.darma-loader-tw-bounce-dots span { width: calc(var(--loader-size, 72px) * .18); height: calc(var(--loader-size, 72px) * .18); border-radius: 9999px; background: var(--loader-color, #8b5cf6); animation: darma-loader-tw-bounce-dots-twBounce var(--loader-speed, 1s) infinite; }
.darma-loader-tw-bounce-dots span:nth-child(2) { animation-delay: calc(var(--loader-speed, 1s) * .15); }
.darma-loader-tw-bounce-dots span:nth-child(3) { animation-delay: calc(var(--loader-speed, 1s) * .3); }
@keyframes darma-loader-tw-bounce-dots-twBounce { 0%, 100% { transform: translateY(-45%); animation-timing-function: cubic-bezier(.8, 0, 1, 1); } 50% { transform: translateY(0); animation-timing-function: cubic-bezier(0, 0, .2, 1); } }

